                    {
                        "호번호": "1.",
                        "호내용": "1. 경관지구",
                        "목": [
                            {
                                "목번호": "가.",
                                "목내용": "가. 자연경관지구 : 산지ㆍ구릉지 등 자연경관을 보호하거나 유지하기 위하여 필요한 지구"
