                            }
                        ]
                    },
                    {
                        "호번호": "8.",
                        "호내용": "8. 개발진흥지구",
                        "목": [
                            {
                                "목번호": "가.",
                                "목내용": "가. 주거개발진흥지구 : 주거기능을 중심으로 개발ㆍ정비할 필요가 있는 지구"
                            },
                            {
                                "목번호": "나.",
                                "목내용": "나. 산업ㆍ유통개발진흥지구 : 공업기능 및 유통ㆍ물류기능을 중심으로 개발ㆍ정비할 필요가 있는 지구"
                            },
